<?php
declare(strict_types=1);
namespace App\PackageModules\Orders;
use App\Platform\Contracts\PlatformRequestInterface;
use App\Platform\Events\EventCatalog;
use App\Platform\Package\AbstractPackageModule;
use App\Platform\Package\PlatformResponse;
use App\Platform\PlatformContext;
final class OrdersModule extends AbstractPackageModule {
 public function name():string{return 'orders';} public function label():string{return 'Заказы';} public function priority():int{return 64;}
 public function adminNav():array{return [['group'=>'Коммерция','path'=>'/admin/orders','label'=>'Заказы','permission'=>'orders.view','icon'=>'shopping-cart']];}
 public function bootPlatform(PlatformContext $ctx):void { parent::bootPlatform($ctx); $ctx->capabilities()->require('api.routes'); $db=$ctx->database(); $http=$ctx->http(); $perms=$ctx->permissions(); $svc=static fn()=>new OrdersService($db,$ctx->events(),$ctx->catalog()); $ctx->orders()->registerBackend(static fn(array $input):array=>$svc()->createOrderFromCheckout($input),static fn(int $id,string $status,?int $actor=null,?string $note=null):array=>$svc()->transitionStatus($id,$status,$actor,$note)); EventCatalog::declare('order.created','orders',['label'=>'Создан заказ','category'=>'commerce','payload'=>['order_id'=>'int','public_id'=>'string','total'=>'number']]); EventCatalog::declare('order.paid','orders',['label'=>'Заказ оплачен','category'=>'commerce','payload'=>['order_id'=>'int','status'=>'string']]); $protected=[$http->authMiddleware(),$http->permissionMiddleware()]; $rate=$http->rateLimitMiddleware(30,60);
  $http->get('/orders/cart',static function(PlatformRequestInterface $r)use($svc){PlatformResponse::json(['data'=>$svc()->getCart(trim((string)($r->query('cart_id')??''))?:null)]);},[$rate]);
  $http->post('/orders/cart/items',static function(PlatformRequestInterface $r)use($svc){try{PlatformResponse::json(['data'=>$svc()->addCartItem((string)($r->input('cart_id')??''),(int)($r->input('product_id')??0),(int)($r->input('quantity')??1))],201);}catch(\InvalidArgumentException $e){PlatformResponse::error($e->getMessage(),422);}},[$rate]);
  $http->put('/orders/cart/items/{id}',static function(PlatformRequestInterface $r,string $id)use($svc){PlatformResponse::json(['data'=>$svc()->updateCartItem((string)($r->input('cart_id')??''),(int)$id,(int)($r->input('quantity')??1))]);},[$rate]);
  $http->post('/orders/checkout',static function(PlatformRequestInterface $r)use($svc){try{$cart=$svc()->getCart((string)($r->input('cart_id')??''));if(empty($cart['items']))PlatformResponse::error('Cart is empty',422);PlatformResponse::json(['data'=>$svc()->createOrderFromCheckout(['items'=>$cart['items'],'email'=>$r->input('email'),'name'=>$r->input('name'),'currency'=>$cart['currency']??'RUB','shipping_total'=>$r->input('shipping_total')??0,'tax_total'=>$r->input('tax_total')??0,'source'=>'cart','note'=>$r->input('note')])],201);}catch(\InvalidArgumentException $e){PlatformResponse::error($e->getMessage(),422);}},[$rate]);
  $http->get('/admin/orders',static function(PlatformRequestInterface $r)use($db,$perms){$perms->require($r->user()??[],'orders.view');$sql='SELECT id,public_id,number,customer_name,COALESCE(email,customer_email) email,grand_total,amount,currency,status,payment_status,fulfillment_status,created_at FROM orders WHERE 1=1';$params=[];$status=trim((string)($r->query('status')??''));$query=trim((string)($r->query('q')??''));if($status!==''){$sql.=' AND status=?';$params[]=$status;}if($query!==''){$sql.=' AND (number LIKE ? OR customer_email LIKE ? OR email LIKE ?)';$like='%'.$query.'%';array_push($params,$like,$like,$like);}$sql.=' ORDER BY id DESC LIMIT 300';PlatformResponse::json(['data'=>$db->all($sql,$params)]);},$protected);
  $http->get('/admin/orders/export',static function(PlatformRequestInterface $r)use($db,$perms,$http){$perms->require($r->user()??[],'orders.export');$rows=$db->all('SELECT number,COALESCE(email,customer_email) email,customer_name,status,payment_status,fulfillment_status,grand_total,currency,created_at FROM orders ORDER BY id DESC LIMIT 10000');$csv=self::csv(['number','email','customer_name','status','payment_status','fulfillment_status','grand_total','currency','created_at'],array_map(static fn(array $row):array=>array_values($row),$rows));$http->download('orders-export.csv',"\xEF\xBB\xBF".$csv);},$protected);
  $http->get('/admin/orders/{id}',static function(PlatformRequestInterface $r,string $id)use($svc,$perms){$perms->require($r->user()??[],'orders.view');$row=$svc()->get((int)$id);if(!$row)PlatformResponse::error('Not found',404);PlatformResponse::json(['data'=>$row]);},$protected);
  foreach(['status'=>'transitionStatus','notes'=>'addNote','refunds'=>'recordRefund'] as $action=>$method){$http->post('/admin/orders/{id}/'.$action,static function(PlatformRequestInterface $r,string $id)use($svc,$perms,$method,$action){$perms->require($r->user()??[],$action==='refunds'?'orders.refund':'orders.manage');try{$args=$action==='status'?[(int)$id,(string)($r->input('status')??''),(int)(($r->user()??[])['sub']??0),$r->input('note')]:($action==='notes'?[(int)$id,(string)($r->input('body')??''),(int)(($r->user()??[])['sub']??0),(bool)($r->input('is_customer_visible')??false)]:[(int)$id,(float)($r->input('amount')??0),$r->input('payment_id')!==null?(int)$r->input('payment_id'):null,$r->input('reason'),(int)(($r->user()??[])['sub']??0)]);PlatformResponse::json(['data'=>$svc()->$method(...$args)],$action==='notes'||$action==='refunds'?201:200);}catch(\InvalidArgumentException $e){PlatformResponse::error($e->getMessage(),422);}},$protected);}
 }

 /** @param list<string> $headers @param list<array<int,mixed>> $rows */
 private static function csv(array $headers,array $rows):string {
  $escape=static function(mixed $value):string{$value=(string)$value;if($value!==''&&in_array($value[0],['=','+','-','@'],true))$value="'".$value;return '"'.str_replace('"','""',$value).'"';};
  $lines=[implode(',',array_map($escape,$headers))];foreach($rows as $row)$lines[]=implode(',',array_map($escape,$row));return implode("\r\n",$lines)."\r\n";
 }
}